msg.payload = { ok: true };
msg.statusCode = 200;
return msg;

const e = msg.payload || {};
const nombres = {voz:'Voz', movimiento_sonido:'Movimiento y sonido', movimiento:'Movimiento', impulsivo:'Sonido impulsivo', sonido:'Sonido', sin_clasificar:'Sin clasificar'};
const hora = new Date((e.started_at || 0) * 1000).toLocaleString('es-AR');
const dur = e.duration ? Math.round(e.duration) + ' s' : '';
msg.evento = e;
msg.topic = 'vigilancia/evento/' + (e.category || 'desconocido');
msg.payload = `${nombres[e.category] || e.category} · ${hora} · ${dur}` + (e.transcript ? ` · "${e.transcript}"` : '');
node.status({fill:'green', shape:'dot', text: msg.payload.slice(0, 40)});
return msg;

msg.url = env.get('VIGD_URL') + '/api/status';
msg.method = 'GET';
msg.headers = { Authorization: 'Bearer ' + (env.get('VIGD_TOKEN') || '') };
return msg;

if (msg.statusCode !== 200) {
  node.status({fill:'red', shape:'ring', text:'HTTP ' + msg.statusCode});
  msg.payload = 'vigd no responde (HTTP ' + msg.statusCode + '). ¿Falta VIGD_TOKEN?';
  return msg;
}
const c = msg.payload.components || {};
const mal = Object.entries(c).filter(([k, v]) => !['ok', 'deshabilitado'].includes(v.state)).map(([k, v]) => `${k}: ${v.state}`);
node.status(mal.length ? {fill:'yellow', shape:'dot', text: mal.join(', ')} : {fill:'green', shape:'dot', text:'todo ok'});
if (!mal.length) return null;
msg.payload = 'Vigilancia con problemas: ' + mal.join(', ');
return msg;
